:root {
    --ink: #0f0f0f;
    --ink-soft: #2d2d2d;
    --ink-muted: #6b6b6b;
    --ink-faint: #a0a0a0;
    --paper: #f7f6f3;
    --paper-warm: #f0ede6;
    --paper-card: #ffffff;
    --accent: #1a472a;
    --accent-light: #e8f0eb;
    --accent-2: #c17f24;
    --accent-2-light: #fdf3e3;
    --danger: #c0392b;
    --danger-light: #fdecea;
    --border: #e4e1da;
    --border-soft: #eeebe4;

    --font-display: 'DM Serif Display', Georgia, serif;
    --font-body: 'DM Sans', system-ui, sans-serif;

    --max-width: 1200px;
    --auth-width: 440px;

    --radius-sm: 6px;
    --radius-md: 12px;
    --radius-lg: 20px;
}

/* ------------------------------------------------------------------ */
/* Reset                                                               */
/* ------------------------------------------------------------------ */

*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
    background: var(--paper);
    color: var(--ink);
    font-family: var(--font-body);
    font-size: 1rem;
    line-height: 1.6;

